"""Independent chat reminder source and compatible projection cursor upgrade."""

SQL = "CREATE TABLE reminder_schedules_chat_upgrade (\n    event_id TEXT PRIMARY KEY,\n    session_id TEXT,\n    event_revision INTEGER NOT NULL CHECK(event_revision >= 1),\n    source_candidate_id TEXT,\n    title TEXT NOT NULL,\n    actor_person_id TEXT NOT NULL,\n    commitment_direction TEXT NOT NULL CHECK(commitment_direction IN (\n        'self_to_other', 'other_to_self', 'mutual', 'not_applicable'\n    )),\n    related_person_ids_json TEXT NOT NULL,\n    scheduled_at TEXT NOT NULL,\n    location TEXT,\n    status TEXT NOT NULL CHECK(status IN (\n        'scheduled', 'delivered', 'completed', 'cancelled', 'stale'\n    )),\n    dedup_key TEXT NOT NULL CHECK(length(dedup_key) = 64),\n    delivered_at TEXT,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n    FOREIGN KEY(event_id) REFERENCES event_current_states(event_id)\n        ON DELETE RESTRICT,\n    FOREIGN KEY(session_id) REFERENCES recording_sessions(session_id)\n        ON DELETE RESTRICT,\n    FOREIGN KEY(source_candidate_id) REFERENCES reminder_candidates(candidate_id)\n        ON DELETE RESTRICT\n);\n\n\nINSERT INTO reminder_schedules_chat_upgrade SELECT * FROM reminder_schedules;\nDROP TABLE reminder_schedules;\nALTER TABLE reminder_schedules_chat_upgrade RENAME TO reminder_schedules;\nCREATE INDEX idx_reminder_schedules_due\nON reminder_schedules(status, scheduled_at, event_id);\n\nCREATE INDEX idx_reminder_schedules_session\nON reminder_schedules(session_id, scheduled_at, event_id);\n\nCREATE INDEX idx_reminder_schedules_dedup\nON reminder_schedules(dedup_key, status, event_id);\n\n\nALTER TABLE sync_cursors RENAME TO sync_cursors_v5;\nCREATE TABLE sync_cursors (device_id TEXT PRIMARY KEY REFERENCES devices(device_id) ON DELETE RESTRICT,\nprojection_version INTEGER NOT NULL CHECK(projection_version = 6), acknowledged_sequence INTEGER NOT NULL CHECK(acknowledged_sequence>=0),updated_at TEXT NOT NULL);\nINSERT INTO sync_cursors SELECT device_id,6,acknowledged_sequence,updated_at FROM sync_cursors_v5;\nDROP TABLE sync_cursors_v5;\n"
